// Simple chat processing
const body = $json.body || $json;
const chatInput = body.chatInput || body.message;
const metadata = body.metadata || {};

if (!chatInput) {
  return [{ json: { error: 'chatInput is required' } }];
}

// Simple response without RAG
const responses = [
  'Merhaba! Size nasıl yardımcı olabilirim?',
  'Sorunuzu anlıyorum. Detaylı bilgi için uzmanlarımızla iletişime geçebilirsiniz.',
  'Bu konuda size yardımcı olmaya çalışacağım.',
  'Başka bir sorunuz var mı?'
];

const randomResponse = responses[Math.floor(Math.random() * responses.length)];

return [{
  json: {
    output: randomResponse,
    followUpPrompts: [
      'Daha fazla bilgi istiyorum',
      'Başka sorularım var',
      'İletişim bilgilerini istiyorum'
    ],
    metadata: {
      responseType: 'simple-webhook',
      timestamp: new Date().toISOString(),
      success: true
    }
  }
}];
